changeSet.sql:
CREATE TABLE calibration_probe_logs ( id SERIAL PRIMARY KEY, provider_id INTEGER NOT NULL REFERENCES providers(id) ON DELETE CASCADE, model_name TEXT NOT NULL,
-- Probe outcome success BOOLEAN NOT NULL, probe_command TEXT, -- exact vLLM command line of the last probe attempt error TEXT,
-- Skip/degradation reasons unsupported_reason TEXT, -- model is permanently unsupported on this node node_unhealthy_reason TEXT, -- node itself is degraded (storage EIO, etc.)
summary JSONB NOT NULL DEFAULT '{}'::jsonb, -- full structured probe payload
recorded_at TIMESTAMPTZ, -- when the worker emitted the event updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
UNIQUE(provider_id, model_name) );
-- Fast lookups by provider CREATE INDEX idx_calibration_probe_logs_provider ON calibration_probe_logs(provider_id);
-- Find the latest probe log for a specific model across providers CREATE INDEX idx_calibration_probe_logs_model_name ON calibration_probe_logs(model_name);
